# yaml-language-server: $schema=../../../schema/checklist.schema.json
kind: Checklist
metadata:
  id: checkbox
  component: checkbox
  source: "material-web@268681913e0a tokens/versions/v0_192/_md-comp-checkbox.scss"
items:
  - { id: target, title: "State layer 영역 40dp", check: { part: root, property: width, expect: 40px } }
  - { id: container-size, title: "컨테이너 18dp", check: { part: container, property: width, expect: 18px } }
  - { id: container-centered, title: "컨테이너가 40dp 영역 중앙(11dp)", check: { part: container, property: left, expect: 11px } }
  - { id: container-shape, title: "컨테이너 모서리 2dp", check: { part: container, property: border-top-left-radius, expect: 2px } }
  - { id: unselected-outline, title: "Unselected outline 2dp on-surface-variant", check: { variant: { type: unselected }, state: enabled, mode: { error: "false" }, part: container, property: box-shadow, expect: "inset 0 0 0 2px {md.sys.color.on-surface-variant}" } }
  - { id: unselected-hover-outline, title: "Unselected hover/focus/pressed outline = on-surface", check: { variant: { type: unselected }, state: [hovered, focused, pressed], mode: { error: "false" }, part: container, property: box-shadow, expect: "inset 0 0 0 2px {md.sys.color.on-surface}" } }
  - { id: unselected-empty, title: "Unselected 컨테이너 비어 있음", check: { variant: { type: unselected }, part: container, property: background-color, expect: transparent } }
  - { id: selected-container, title: "Selected·Indeterminate 컨테이너 = primary", check: { variant: { type: [selected, indeterminate] }, state: [enabled, hovered, focused, pressed], mode: { error: "false" }, part: container, property: background-color, expect: "{md.sys.color.primary}" } }
  - { id: selected-check, title: "Selected면 체크 표시", check: { variant: { type: selected }, part: check, property: display, expect: block } }
  - { id: selected-no-dash, title: "Selected면 대시 숨김", check: { variant: { type: selected }, part: dash, property: display, expect: none } }
  - { id: indeterminate-dash, title: "Indeterminate면 대시 표시, 체크 숨김", check: { variant: { type: indeterminate }, part: dash, property: display, expect: block } }
  - { id: indeterminate-no-check, title: "Indeterminate면 체크 숨김", check: { variant: { type: indeterminate }, part: check, property: display, expect: none } }
