  - { id: icon-color, title: "체크 아이콘 = on-primary", check: { variant: { type: selected }, state: enabled, mode: { error: "false" }, part: check, property: --ou-icon-fill, expect: "{md.sys.color.on-primary}" } }
  - { id: error-outline, title: "Error unselected outline = error", check: { variant: { type: unselected }, state: [enabled, hovered, focused, pressed], mode: { error: "true" }, part: container, property: box-shadow, expect: "inset 0 0 0 2px {md.sys.color.error}" } }
  - { id: error-selected, title: "Error selected 컨테이너 = error", check: { variant: { type: [selected, indeterminate] }, state: [enabled, hovered, focused, pressed], mode: { error: "true" }, part: container, property: background-color, expect: "{md.sys.color.error}" } }
  - { id: error-icon, title: "Error selected 아이콘 = on-error", check: { variant: { type: selected }, state: enabled, mode: { error: "true" }, part: check, property: --ou-icon-fill, expect: "{md.sys.color.on-error}" } }
  - { id: disabled-selected, title: "Disabled selected 컨테이너 on-surface 38%", check: { variant: { type: [selected, indeterminate] }, state: disabled, part: container, property: background-color, expect: "color-mix(in srgb, {md.sys.color.on-surface} 38%, transparent)" } }
  - { id: disabled-selected-icon, title: "Disabled selected 아이콘 = surface", check: { variant: { type: selected }, state: disabled, part: check, property: --ou-icon-fill, expect: "{md.sys.color.surface}" } }
  - { id: disabled-unselected, title: "Disabled unselected outline on-surface 38% (error 무시)", check: { variant: { type: unselected }, state: disabled, part: container, property: box-shadow, expect: "inset 0 0 0 2px color-mix(in srgb, {md.sys.color.on-surface} 38%, transparent)" } }
  - { id: layer-shape, title: "State layer 원형", check: { part: stateLayer, property: border-top-left-radius, expect: "{md.sys.shape.corner-full}" } }
  - { id: enabled-layer, title: "Enabled state layer 없음", check: { state: enabled, part: stateLayer, property: opacity, expect: 0 } }
  - { id: hover-layer, title: "Hover state layer 8%", check: { state: hovered, part: stateLayer, property: opacity, expect: "{md.sys.state.hover-state-layer-opacity}" } }
  - { id: focus-layer, title: "Focus state layer 10%", check: { state: focused, part: stateLayer, property: opacity, expect: "{md.sys.state.focus-state-layer-opacity}" } }
  - { id: pressed-layer, title: "Pressed state layer 10%", check: { state: pressed, part: stateLayer, property: opacity, expect: "{md.sys.state.pressed-state-layer-opacity}" } }
  - { id: unselected-pressed-layer, title: "Unselected pressed layer = primary (선택될 색 미리보기)", check: { variant: { type: unselected }, state: pressed, mode: { error: "false" }, part: stateLayer, property: background-color, expect: "{md.sys.color.primary}" } }
