  - { id: animation, title: "선택 전환 애니메이션 — v0.1 어휘로 미표현", manual: true }
  - { id: touch-target, title: "터치 타깃 48dp", manual: true }
  - { id: focus-ring, title: "포커스 링 — v0.1 어휘로 미표현", manual: true, hint: { state: focused } }

