kind: Checklist
metadata:
  id: icon-button
  component: icon-button
  source: "material-web@268681913e0a tokens/versions/v0_192/_md-comp-{icon-button,filled-icon-button,filled-tonal-icon-button,outlined-icon-button}.scss"
items:
