  - { id: size-h, title: "컨테이너 높이 40dp", check: { part: root, property: height, expect: 40px } }
  - { id: shape, title: "원형(corner-full)", check: { part: root, property: border-top-left-radius, expect: "{md.sys.shape.corner-full}" } }
  - { id: icon-size, title: "아이콘 24dp", check: { part: icon, property: width, expect: 24px } }
  - { id: standard-transparent, title: "Standard·Outlined 컨테이너 없음", check: { mode: { style: [standard, outlined] }, part: root, property: background-color, expect: transparent } }
  - { id: standard-icon, title: "Standard 아이콘 = on-surface-variant", check: { state: [enabled, hovered, focused, pressed], mode: { style: standard }, part: icon, property: --ou-icon-fill, expect: "{md.sys.color.on-surface-variant}" } }
  - { id: filled-container, title: "Filled 컨테이너 = primary", check: { state: [enabled, hovered, focused, pressed], mode: { style: filled }, part: root, property: background-color, expect: "{md.sys.color.primary}" } }
  - { id: filled-icon, title: "Filled 아이콘 = on-primary", check: { state: enabled, mode: { style: filled }, part: icon, property: --ou-icon-fill, expect: "{md.sys.color.on-primary}" } }
  - { id: tonal-container, title: "Tonal 컨테이너 = secondary-container", check: { state: enabled, mode: { style: tonal }, part: root, property: background-color, expect: "{md.sys.color.secondary-container}" } }
  - { id: tonal-icon, title: "Tonal 아이콘 = on-secondary-container", check: { state: enabled, mode: { style: tonal }, part: icon, property: --ou-icon-fill, expect: "{md.sys.color.on-secondary-container}" } }
  - { id: outlined-outline, title: "Outlined 1dp outline", check: { state: [enabled, hovered, focused, pressed], mode: { style: outlined }, part: root, property: box-shadow, expect: "inset 0 0 0 1px {md.sys.color.outline}" } }
  - { id: outlined-disabled-outline, title: "Outlined disabled outline = on-surface 12%", check: { state: disabled, mode: { style: outlined }, part: root, property: box-shadow, expect: "inset 0 0 0 1px color-mix(in srgb, {md.sys.color.on-surface} 12%, transparent)" } }
  - { id: outlined-pressed-icon, title: "Outlined pressed 아이콘 = on-surface", check: { state: pressed, mode: { style: outlined }, part: icon, property: --ou-icon-fill, expect: "{md.sys.color.on-surface}" } }
  - { id: disabled-container, title: "Filled·Tonal disabled 컨테이너 on-surface 12%", check: { state: disabled, mode: { style: [filled, tonal] }, part: root, property: background-color, expect: "color-mix(in srgb, {md.sys.color.on-surface} 12%, transparent)" } }
  - { id: disabled-icon, title: "Disabled 아이콘 on-surface 38%", check: { state: disabled, part: icon, property: --ou-icon-fill-opacity, expect: 0.38 } }
  - { id: enabled-layer, title: "Enabled state layer 없음", check: { state: enabled, part: stateLayer, property: opacity, expect: 0 } }
  - { id: hover-layer, title: "Hover state layer 8%", check: { state: hovered, part: stateLayer, property: opacity, expect: "{md.sys.state.hover-state-layer-opacity}" } }
  - { id: focus-layer, title: "Focus state layer 10% (Outlined는 토큰상 8%)", check: { state: focused, mode: { style: [standard, filled, tonal] }, part: stateLayer, property: opacity, expect: "{md.sys.state.focus-state-layer-opacity}" } }
  - { id: outlined-focus-layer, title: "Outlined focus state layer 8% (v0.192 토큰 그대로)", check: { state: focused, mode: { style: outlined }, part: stateLayer, property: opacity, expect: 0.08 } }
  - { id: pressed-layer, title: "Pressed state layer 10%", check: { state: pressed, part: stateLayer, property: opacity, expect: "{md.sys.state.pressed-state-layer-opacity}" } }
  - { id: layer-shape, title: "State layer 원형", check: { part: stateLayer, property: border-top-left-radius, expect: "{md.sys.shape.corner-full}" } }
  - { id: focus-ring, title: "포커스 링 — v0.1 어휘로 미표현임을 확인", manual: true, hint: { state: focused } }
  - { id: ripple, title: "pressed 리플 — 정적 프리뷰는 state layer만 표시", manual: true, hint: { state: pressed } }
  - { id: touch-target, title: "터치 타깃 48dp 확보", manual: true }
  - { id: tooltip, title: "아이콘 의미를 툴팁/접근성 라벨로 보완", manual: true }

files.components/checkbox.yaml:
# yaml-language-server: $schema=../../../schema/component.schema.json
# M3 checkbox, material-web v0.192 tokens. `type` is a variant (it shows the check or dash icon);
# error only changes colors, so it is a mode prop (data.tokens `$when: error=…`).
kind: Component
metadata:
  id: checkbox
  name: Checkbox
  description: "M3 checkbox. The check glyph uses Material Icons `check`, not M3's custom check-mark path."
data:
  props:
    error: { type: mode, values: ["false", "true"], default: "false", description: "\"true\" shows error colors (token mode; the UI tree is the same)" }
  variants:
    type:
      values:
        unselected:    {}
        selected:      {}
        indeterminate: { description: "Partially selected (parent of mixed children)" }
      default: unselected
  states: [enabled, hovered, focused, pressed, disabled]
  # The tokens this component uses ("{checkbox.<name>}"), values from material-web v0.192 component tokens. $when = the value for that error.
  tokens:
    state-layer-size: { $type: dimension, $value: { value: 40, unit: px } }
    container-offset: { $type: dimension, $value: { value: 11, unit: px } }
    container-size: { $type: dimension, $value: { value: 18, unit: px } }
    state-layer-shape: { $type: dimension, $value: "{md.sys.shape.corner-full}" }
    enabled-state-layer-opacity: { $type: number, $value: "{md.sys.opacity.zero}" }
    unselected-hover-state-layer-color:
      $type: color
      $value: "{md.sys.color.on-surface}"
      $when:
        error=true: "{md.sys.color.error}"
    container-shape: { $type: dimension, $value: { value: 2, unit: px } }
    unselected-container-color: { $type: color, $value: "{md.sys.color.transparent}" }
    unselected-outline-color:
      $type: color
      $value: "{md.sys.color.on-surface-variant}"
      $when:
        error=true: "{md.sys.color.error}"
    unselected-outline-width: { $type: dimension, $value: { value: 2, unit: px } }
    icon-size: { $type: dimension, $value: { value: 18, unit: px } }
    selected-icon-color:
      $type: color
      $value: "{md.sys.color.on-primary}"
      $when:
        error=true: "{md.sys.color.on-error}"
    unselected-hover-state-layer-opacity: { $type: number, $value: "{md.sys.state.hover-state-layer-opacity}" }
    unselected-hover-outline-color:
      $type: color
      $value: "{md.sys.color.on-surface}"
      $when:
        error=true: "{md.sys.color.error}"
    unselected-focus-state-layer-opacity: { $type: number, $value: "{md.sys.state.focus-state-layer-opacity}" }
    unselected-focus-outline-color:
      $type: color
      $value: "{md.sys.color.on-surface}"
      $when:
        error=true: "{md.sys.color.error}"
    unselected-pressed-state-layer-opacity: { $type: number, $value: "{md.sys.state.pressed-state-layer-opacity}" }
    unselected-pressed-state-layer-color:
      $type: color
      $value: "{md.sys.color.primary}"
      $when:
        error=true: "{md.sys.color.error}"
    unselected-pressed-outline-color:
      $type: color
      $value: "{md.sys.color.on-surface}"
      $when:
        error=true: "{md.sys.color.error}"
    unselected-disabled-outline-color: { $type: color, $value: "{md.sys.color.on-surface}" }
    unselected-disabled-container-opacity: { $type: number, $value: 0.38 }
    selected-hover-state-layer-color:
      $type: color
      $value: "{md.sys.color.primary}"
      $when:
        error=true: "{md.sys.color.error}"
    selected-container-color:
      $type: color
      $value: "{md.sys.color.primary}"
      $when:
        error=true: "{md.sys.color.error}"
    selected-outline-width: { $type: dimension, $value: { value: 0, unit: px } }
    selected-pressed-state-layer-color:
      $type: color
      $value: "{md.sys.color.on-surface}"
      $when:
        error=true: "{md.sys.color.error}"
    selected-disabled-container-color: { $type: color, $value: "{md.sys.color.on-surface}" }
    selected-disabled-container-opacity: { $type: number, $value: 0.38 }
    selected-disabled-icon-color: { $type: color, $value: "{md.sys.color.surface}" }
  anatomy:
    root:
      kind: frame
      layout: { direction: none, width: "{checkbox.state-layer-size}", height: "{checkbox.state-layer-size}" }
      children:
        stateLayer: { kind: frame, layout: { position: absolute, width: fill, height: fill } }
        container:  { kind: frame, layout: { x: "{checkbox.container-offset}", y: "{checkbox.container-offset}", width: "{checkbox.container-size}", height: "{checkbox.container-size}" } }
        check:      { kind: instance, component: icon-check }
        dash:       { kind: instance, component: icon-remove }
  styles:
    # type changes the UI tree (check / dash icons); error colors come from the checkbox-error token mode
    base:
      enabled:
        stateLayer: { cornerRadius: "{checkbox.state-layer-shape}", opacity: "{checkbox.enabled-state-layer-opacity}", fill: "{checkbox.unselected-hover-state-layer-color}" }
        container:  { cornerRadius: "{checkbox.container-shape}", fill: "{checkbox.unselected-container-color}", strokeColor: "{checkbox.unselected-outline-color}", strokeWidth: "{checkbox.unselected-outline-width}" }
        check:      { x: "{checkbox.container-offset}", y: "{checkbox.container-offset}", width: "{checkbox.icon-size}", height: "{checkbox.icon-size}", visible: false, fill: "{checkbox.selected-icon-color}" }
        dash:       { x: "{checkbox.container-offset}", y: "{checkbox.container-offset}", width: "{checkbox.icon-size}", height: "{checkbox.icon-size}", visible: false, fill: "{checkbox.selected-icon-color}" }
      hovered:
        stateLayer: { opacity: "{checkbox.unselected-hover-state-layer-opacity}" }
        container:  { strokeColor: "{checkbox.unselected-hover-outline-color}" }
      focused:
        stateLayer: { opacity: "{checkbox.unselected-focus-state-layer-opacity}" }
        container:  { strokeColor: "{checkbox.unselected-focus-outline-color}" }
      pressed:
        stateLayer: { opacity: "{checkbox.unselected-pressed-state-layer-opacity}", fill: "{checkbox.unselected-pressed-state-layer-color}" }
        container:  { strokeColor: "{checkbox.unselected-pressed-outline-color}" }
      disabled:
        container: { strokeColor: "{checkbox.unselected-disabled-outline-color}", strokeOpacity: "{checkbox.unselected-disabled-container-opacity}" }

    # selected and indeterminate share container styling (spec v0.1 has no OR in variant expressions)
    type=selected:
      enabled:
        stateLayer: { fill: "{checkbox.selected-hover-state-layer-color}" }
        container:  { fill: "{checkbox.selected-container-color}", strokeWidth: "{checkbox.selected-outline-width}" }
        check:      { visible: true }
      pressed:
        stateLayer: { fill: "{checkbox.selected-pressed-state-layer-color}" }
      disabled:
        container: { fill: "{checkbox.selected-disabled-container-color}", fillOpacity: "{checkbox.selected-disabled-container-opacity}" }
        check:     { fill: "{checkbox.selected-disabled-icon-color}" }
    type=indeterminate:
      enabled:
        stateLayer: { fill: "{checkbox.selected-hover-state-layer-color}" }
        container:  { fill: "{checkbox.selected-container-color}", strokeWidth: "{checkbox.selected-outline-width}" }
        dash:       { visible: true }
      pressed:
        stateLayer: { fill: "{checkbox.selected-pressed-state-layer-color}" }
      disabled:
        container: { fill: "{checkbox.selected-disabled-container-color}", fillOpacity: "{checkbox.selected-disabled-container-opacity}" }
        dash:      { fill: "{checkbox.selected-disabled-icon-color}" }

