# M3 elevation shadows, transcribed from material-web@268681913e0a elevation/internal/_elevation.scss
# (key shadow at 30% opacity + ambient shadow at 15% of md.sys.color.shadow = #000).
md:
  sys:
    elevation-shadow:
      $type: shadow
      level0:
