    state-layer-color: { $type: color, $value: "{color.on-surface}" }
    state-layer-opacity: { $type: number, $value: "{opacity.none}" }
    hover-state-layer-opacity: { $type: number, $value: "{opacity.hover}" }
    heading-color: { $type: color, $value: "{color.on-surface}" }
    heading-typography: { $type: typography, $value: "{type.body}" }
  anatomy:
    root:
      kind: frame
      layout: { direction: column, gap: "{card.gap}", padding: ["{card.padding}", "{card.padding}", "{card.padding-bottom}", "{card.padding}"], width: "{card.width}", height: hug }
      children:
        stateLayer: { kind: frame, layout: { position: absolute, width: fill, height: fill } }
        heading:    { kind: text, text: { prop: title } }
        body:       { kind: slot, prop: content, layout: { direction: row, gap: "{card.gap}", width: fill } }
  styles:
    base:
      enabled:
        root:       { fill: "{card.container-color}", cornerRadius: "{card.corner-radius}", shadow: "{card.shadow}", strokeColor: "{card.outline-color}", strokeWidth: "{card.outline-width}", strokeAlign: outside }
        stateLayer: { fill: "{card.state-layer-color}", opacity: "{card.state-layer-opacity}", cornerRadius: "{card.corner-radius}" }
        heading:    { color: "{card.heading-color}", typography: "{card.heading-typography}" }
      hovered:
        stateLayer: { opacity: "{card.hover-state-layer-opacity}" }

files.components/gallery.yaml:
# yaml-language-server: $schema=../../../schema/component.schema.json
kind: Component
metadata: { id: gallery, name: Gallery, description: "Conformance: grid, wrap, absolute badge, image, gradient fill, x-figma, orientation- and window-dependent tokens" }
data:
  props:
    caption: { type: text, default: "{text.gallery.caption}" }
  tokens:
    gap:        { $type: dimension, $value: { value: 12, unit: px }, $when: { orientation=landscape: { value: 16, unit: px } } }
    grid-gap:   { $type: dimension, $value: { value: 8, unit: px }, $when: { orientation=landscape: { value: 12, unit: px } } }
    padding:    { $type: dimension, $value: "{space.inset}" }
    tags-gap:   { $type: dimension, $value: "{space.xs}" }
    tags-width: { $type: dimension, $value: { value: 200, unit: px }, $when: { window=medium: { value: 280, unit: px }, window=expanded: { value: 360, unit: px } } }
    container-color: { $type: color, $value: "{color.surface}" }
    corner-radius:   { $type: dimension, $value: "{radius.medium}" }
    corner-none:     { $type: dimension, $value: "{radius.none}" }
    scrim:           { $type: gradient, $value: "{gradient.scrim}" }
    thumb-size:      { $type: dimension, $value: { value: 96, unit: px } }
    thumb-radius:    { $type: dimension, $value: "{radius.small}" }
    badge-offset:    { $type: dimension, $value: "{space.xs}" }
    badge-color:     { $type: color, $value: "{color.on-primary}" }
    badge-typography: { $type: typography, $value: "{type.label}" }
    caption-color:   { $type: color, $value: "{color.on-surface}" }
    caption-typography: { $type: typography, $value: "{type.body}" }
  anatomy:
    root:
      kind: frame
      layout: { direction: column, gap: "{gallery.gap}", padding: "{gallery.padding}", width: hug, height: hug }
      children:
        grid:
          kind: frame
          layout: { direction: grid, grid: { columns: 2, rows: 2 }, gap: "{gallery.grid-gap}", crossGap: "{gallery.grid-gap}" }
          children:
            photo: { kind: image, src: "data:image/svg+xml;utf8,<svg xmlns='http://www.w3.org/2000/svg' width='96' height='96'><rect width='96' height='96' fill='%23d0bcff'/></svg>" }
            badge: { kind: text, text: "{text.gallery.badge}" }
        tags:
          kind: frame
          layout: { direction: row, wrap: true, gap: "{gallery.tags-gap}", crossGap: "{gallery.tags-gap}", width: "{gallery.tags-width}" }
          children:
            tagA: { kind: text, text: "{text.gallery.tag-a}" }
            tagB: { kind: text, text: "{text.gallery.tag-b}" }
            tagC: { kind: text, text: "{text.gallery.tag-c}" }
        caption: { kind: text, text: { prop: caption } }
  styles:
    base:
      enabled:
        root:    { fill: "{gallery.container-color}", cornerRadius: ["{gallery.corner-radius}", "{gallery.corner-radius}", "{gallery.corner-none}", "{gallery.corner-none}"] }
        grid:    { fill: "{gallery.scrim}" }
        photo:   { width: "{gallery.thumb-size}", height: "{gallery.thumb-size}", cornerRadius: "{gallery.thumb-radius}" }
        badge:   { position: absolute, x: "{gallery.badge-offset}", y: "{gallery.badge-offset}", color: "{gallery.badge-color}", typography: "{gallery.badge-typography}" }
        caption: { color: "{gallery.caption-color}", typography: "{gallery.caption-typography}", textAlign: center }
  x-figma:
    parts:
      root: { blendMode: PASS_THROUGH, clipsContent: true }

